        console2.log("minted", minted);
        console2.log("PROFIT_USD", unbacked);
        require(rateAfter > rateBefore * 10, "rate not >10x");
        require(token.balanceOf(atk) > fairCollateralValue * 10, "no material unbacked mint");
    }

}

